PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "__EFMigrationsLock" (
    "Id" INTEGER NOT NULL CONSTRAINT "PK___EFMigrationsLock" PRIMARY KEY,
    "Timestamp" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" TEXT NOT NULL CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY,
    "ProductVersion" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "Birth" (
    "Id" INTEGER NOT NULL CONSTRAINT "PK_Birth" PRIMARY KEY AUTOINCREMENT,
    "Date" TEXT NULL,
    "Place" TEXT NOT NULL,
    "Country" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "Leagues" (
    "Id" INTEGER NOT NULL CONSTRAINT "PK_Leagues" PRIMARY KEY AUTOINCREMENT,
    "Name" TEXT NOT NULL,
    "Country" TEXT NOT NULL,
    "Logo" TEXT NOT NULL,
    "Flag" TEXT NOT NULL,
    "Season" INTEGER NULL
);
CREATE TABLE IF NOT EXISTS "Teams" (
    "Id" INTEGER NOT NULL CONSTRAINT "PK_Teams" PRIMARY KEY AUTOINCREMENT,
    "Name" TEXT NOT NULL,
    "Code" TEXT NOT NULL,
    "Country" TEXT NOT NULL,
    "Founded" TEXT NULL,
    "National" INTEGER NOT NULL,
    "Logo" TEXT NOT NULL,
    "CurrentLeagueRank" INTEGER NOT NULL,
    "Points" INTEGER NULL,
    "GoalsDiff" INTEGER NULL,
    "Played" INTEGER NULL,
    "Win" INTEGER NULL,
    "Draw" INTEGER NULL,
    "Lose" INTEGER NULL,
    "GoalsFor" INTEGER NULL,
    "GoalsAgainst" INTEGER NULL,
    "LeagueId" INTEGER NOT NULL,
    CONSTRAINT "FK_Teams_Leagues_LeagueId" FOREIGN KEY ("LeagueId") REFERENCES "Leagues" ("Id") ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "Players" (
    "Id" INTEGER NOT NULL CONSTRAINT "PK_Players" PRIMARY KEY AUTOINCREMENT,
    "Age" INTEGER NULL,
    "BirthId" INTEGER NULL,
    "FirstName" TEXT NOT NULL,
    "Height" REAL NULL,
    "LastName" TEXT NOT NULL,
    "Name" TEXT NOT NULL,
    "Nationality" TEXT NOT NULL,
    "Number" INTEGER NULL,
    "Photo" TEXT NOT NULL,
    "Position" TEXT NULL,
    "TeamId" INTEGER NULL,
    CONSTRAINT "FK_Players_Birth_BirthId" FOREIGN KEY ("BirthId") REFERENCES "Birth" ("Id"),
    CONSTRAINT "FK_Players_Teams_TeamId" FOREIGN KEY ("TeamId") REFERENCES "Teams" ("Id")
);
CREATE INDEX "IX_Teams_LeagueId" ON "Teams" ("LeagueId");
CREATE INDEX "IX_Players_BirthId" ON "Players" ("BirthId");
CREATE INDEX "IX_Players_TeamId" ON "Players" ("TeamId");
COMMIT;
